+        "aws_lambda_handler",
+        "breakdown_metrics",
+        "classes_excluded_from_instrumentation",
+        "cloud_provider",
+        "data_flush_timeout",
+        "disable_metrics",
+        "disable_send",
+        "enabled",
+        "enable_public_api_annotation_inheritance",
+        "environment",
+        "global_labels",
+        "hostname",
+        "include_process_args",
+        "log_ecs_formatter_allow_list",
+        "log_ecs_reformatting_additional_fields",
+        "log_ecs_reformatting_dir",
+        "log_file",
+        "log_file_size",
+        "log_format_file",
+        "log_format_sout",
+        "max_queue_size",
+        "metrics_interval",
+        "plugins_dir",
+        "profiling_inferred_spans_lib_directory",
+        "secret_token",
+        "service_name",
+        "service_node_name",
+        "service_version",
